import socket,json
out=[]
for family,address in [(socket.AF_INET,('198.51.100.1',443)),(socket.AF_INET6,('2001:db8::1',443))]:
 s=socket.socket(family);s.settimeout(1)
 try:s.connect(address);out.append({'family':family,'connected':True})
 except OSError as e:out.append({'family':family,'errno':e.errno})
 finally:s.close()
print(json.dumps(out))
